"""SYNTHETIC metadata fixtures only; no tensor/model/weight operations."""
import unittest
from math import prod
import json
import sys
from coverage_check import map_key, check_coverage, parse_request


def synthetic_r101_metadata():
    """Independent fixed architecture fixture, not generated by the checker."""
    source, target = {}, {}
    def meta(shape, dtype='torch.float32'):
        return dict(dtype=dtype, shape=list(shape), numel=prod(shape))
    def conv(sk, tk, shape):
        source[sk] = meta(shape)
        target['backbone.bottom_up.'+tk] = meta(shape)
    def norm(sk, tk, width):
        for field in ('weight', 'bias', 'running_mean', 'running_var'):
            source[sk+'.'+field] = meta([width])
            target['backbone.bottom_up.'+tk+'.'+field] = meta([width])
        source[sk+'.num_batches_tracked'] = meta([], 'torch.int64')
    conv('conv1.weight', 'stem.conv1.weight', [64,3,7,7])
    norm('bn1', 'stem.conv1.norm', 64)
    previous = 64
    for stage, (count, width) in enumerate(((3,64),(4,128),(23,256),(3,512)), 1):
        for block in range(count):
            s, t = 'layer%d.%d.'%(stage,block), 'res%d.%d.'%(stage+1,block)
            conv(s+'conv1.weight',t+'conv1.weight',[width,previous,1,1])
            norm(s+'bn1',t+'conv1.norm',width)
            conv(s+'conv2.weight',t+'conv2.weight',[width,width,3,3])
            norm(s+'bn2',t+'conv2.norm',width)
            conv(s+'conv3.weight',t+'conv3.weight',[width*4,width,1,1])
            norm(s+'bn3',t+'conv3.norm',width*4)
            if block == 0:
                conv(s+'downsample.0.weight',t+'shortcut.weight',[width*4,previous,1,1])
                norm(s+'downsample.1',t+'shortcut.norm',width*4)
            target['backbone.bottom_up.'+t+'conv2_offset.weight'] = meta([27,width,3,3])
            target['backbone.bottom_up.'+t+'conv2_offset.bias'] = meta([27])
            previous = width*4
    source['fc.weight'],source['fc.bias'] = meta([1000,2048]),meta([1000])
    return source, target


class CoverageTests(unittest.TestCase):
    def test_explicit_known_conversion(self):
        self.assertEqual(map_key('conv1.weight'), 'backbone.bottom_up.stem.conv1.weight')
        self.assertEqual(map_key('bn1.running_var'), 'backbone.bottom_up.stem.conv1.norm.running_var')
        self.assertEqual(map_key('layer3.22.bn2.running_mean'), 'backbone.bottom_up.res4.22.conv2.norm.running_mean')
        self.assertEqual(map_key('layer4.0.downsample.1.bias'), 'backbone.bottom_up.res5.0.shortcut.norm.bias')

    def test_full_synthetic_plan_has_all520_and_no_offset_or_head_load(self):
        source, target = synthetic_r101_metadata()
        report = check_coverage(source, target)
        self.assertEqual(report['mapped_key_count'],520)
        self.assertEqual(report['mapped_numel'],42605504)
        self.assertEqual(len(report['target_unloaded_plan']),66)
        self.assertEqual(len(report['source_excluded']),106)
        self.assertEqual([report['stages'][k]['mapped_keys'] for k in ('stem','res2','res3','res4','res5')],[5,50,65,350,50])
        self.assertFalse(report['actual_tensor_load_verified'])
        self.assertTrue(all('conv2_offset.' not in x['target'] for x in report['mapping']))

    def test_partial_late_R101_block_cannot_claim_complete_backbone(self):
        source, target = synthetic_r101_metadata()
        del source['layer3.22.bn2.running_var']
        del target['backbone.bottom_up.res4.22.conv2.norm.running_var']
        with self.assertRaisesRegex(ValueError, 'Missing required source'):
            check_coverage(source, target)

    def test_same_wrong_shapes_on_both_sides_do_not_certify_architecture(self):
        source, target = synthetic_r101_metadata()
        wrong = dict(dtype='torch.float32',shape=[64,3,3,7],numel=4032)
        source['conv1.weight'] = dict(wrong)
        target['backbone.bottom_up.stem.conv1.weight'] = dict(wrong)
        with self.assertRaisesRegex(ValueError, 'Architecture shape'):
            check_coverage(source, target)

    def test_duplicate_JSON_keys_rejected_before_a_dictionary_hides_them(self):
        bad = '{"schema":"R101-explicit-metadata-request-v1","source":{"conv1.weight":{},"conv1.weight":{}},"target":{}}'
        with self.assertRaisesRegex(ValueError,'Duplicate JSON key'):
            parse_request(bad)

    def test_missing_FrozenBN_components_are_rejected_before_any_loader(self):
        for suffix in ('weight','bias','running_mean','running_var'):
            with self.subTest(field=suffix):
                source,target = synthetic_r101_metadata()
                del source['layer4.2.bn3.'+suffix]
                with self.assertRaisesRegex(ValueError,'Missing required source'):
                    check_coverage(source,target)

    def test_noncanonical_foreign_and_source_offset_keys_are_rejected(self):
        for key in ('module.conv1.weight','layer03.0.conv1.weight','layer3.023.bn2.weight',
                    'layer4.3.conv1.weight','layer3.22.downsample.1.bias',
                    'layer2.1.conv2_offset.weight','layer2.4.bn1.num_batches_tracked','fc.extra'):
            with self.subTest(key=key):
                source,target = synthetic_r101_metadata()
                source[key] = dict(dtype='torch.float32',shape=[1],numel=1)
                with self.assertRaises(ValueError):
                    check_coverage(source,target)

    def test_foreign_target_layers_and_FrozenBN_counters_are_rejected(self):
        for key in ('backbone.fpn_lateral2.weight','head.class_logits.weight',
                    'backbone.bottom_up.res2.0.conv1.norm.num_batches_tracked',
                    'backbone.bottom_up.res4.23.conv1.weight'):
            with self.subTest(key=key):
                source,target = synthetic_r101_metadata()
                target[key] = dict(dtype='torch.float32',shape=[1],numel=1)
                with self.assertRaisesRegex(ValueError,'Unknown target'):
                    check_coverage(source,target)

    def test_full_DCN_offset_layout_is_required_but_never_transferred(self):
        source,target = synthetic_r101_metadata()
        del target['backbone.bottom_up.res4.22.conv2_offset.bias']
        with self.assertRaisesRegex(ValueError,'Missing required target'):
            check_coverage(source,target)
        source,target = synthetic_r101_metadata()
        target['backbone.bottom_up.res4.22.conv2_offset.weight'] = dict(dtype='torch.float32',shape=[18,256,3,3],numel=41472)
        with self.assertRaisesRegex(ValueError,'Architecture shape'):
            check_coverage(source,target)

    def test_metadata_cannot_hide_dtype_numel_bool_or_digest_errors(self):
        mutations = ({'dtype':'torch.float64'},{'numel':True},{'numel':'64'},
                     {'shape':[True],'numel':1},{'sha256':'not-a-digest'},
                     {'device':'cuda'})
        for mutation in mutations:
            with self.subTest(mutation=mutation):
                source,target = synthetic_r101_metadata()
                source['bn1.weight'].update(mutation)
                with self.assertRaises(ValueError):
                    check_coverage(source,target)

    def test_optional_legacy_counters_and_classifier_can_be_absent(self):
        source,target = synthetic_r101_metadata()
        source={k:v for k,v in source.items() if not k.startswith('fc.') and not k.endswith('num_batches_tracked')}
        report=check_coverage(source,target)
        self.assertEqual(report['mapped_key_count'],520)
        self.assertEqual(report['source_excluded'],[])
        self.assertEqual([report['stages'][k]['required_numel'] for k in ('stem','res2','res3','res4','res5')],
                         [9664,218624,1226752,26163200,14987264])

    def test_optional_digests_remain_separate_and_inputs_are_not_modified(self):
        source,target = synthetic_r101_metadata()
        source['conv1.weight']['sha256']='a'*64
        target['backbone.bottom_up.stem.conv1.weight']['sha256']='b'*64
        before=json.dumps([source,target],sort_keys=True)
        report=check_coverage(source,target)
        self.assertEqual(json.dumps([source,target],sort_keys=True),before)
        record=next(r for r in report['mapping'] if r['source']=='conv1.weight')
        self.assertNotEqual(record['source_metadata']['sha256'],record['target_initial_metadata']['sha256'])
        record['source_metadata']['shape'][0]=999
        self.assertEqual(source['conv1.weight']['shape'][0],64)
        self.assertFalse(report['actual_tensor_load_verified'])
        self.assertFalse(report['actual_target_values_unchanged_verified'])
        self.assertFalse(report['source_provenance_verified'])

    def test_metadata_request_schema_nonfinite_and_nested_duplicates(self):
        valid=dict(schema='R101-explicit-metadata-request-v1',source={},target={})
        self.assertEqual(parse_request(json.dumps(valid)),valid)
        for raw in ('{"schema":"R101-explicit-metadata-request-v1","source":{},"target":{"x":{},"x":{}}}',
                    '{"schema":"R101-explicit-metadata-request-v1","source":{"x":NaN},"target":{}}',
                    '{"schema":"R101-explicit-metadata-request-v1","source":{},"target":{},"qualified":true}'):
            with self.subTest(raw=raw),self.assertRaises(ValueError):
                parse_request(raw)

    def test_no_scientific_libraries_imported(self):
        self.assertFalse(any(k.split('.')[0] in ('torch','numpy') for k in sys.modules))


if __name__ == '__main__':
    unittest.main()
